<?php require "vendor/autoload.php"; $app = require_once "bootstrap/app.php"; $kernel = $app->make(Illuminate\Contracts\Console\Kernel::class); $kernel->bootstrap(); $chalan = \App\Models\GenerateChalan::where("chalan_no", "59")->first(); $chalanNos = [$chalan->chalan_no]; $billItems = \App\Models\GenerateBillItem::whereIn("sr_no", $chalanNos)->with("generateBill")->get(); echo "Found " . $billItems->count() . " items.\n"; foreach($billItems as $item) { echo "sr_no: " . $item->sr_no . ", generateBill exists: " . ($item->generateBill ? "Yes, bill_no=" . $item->generateBill->bill_no . ", is_draft=" . $item->generateBill->is_draft : "No") . "\n"; } $matched = $billItems->firstWhere("sr_no", $chalan->chalan_no); echo "firstWhere matched: " . ($matched ? "Yes" : "No") . "\n"; 
